sp_widget.client_script:
api.controller = function() {

    var c = this;


    /*
     * =========================================================
     * VARIABLES
     * =========================================================
     */

    c.search = '';
    c.statusFilter = 'all';
    c.industryFilter = 'all';
    c.selectedCompany = null;


    /*
     * =========================================================
     * FILTER COMPANIES
     * =========================================================
     */

    c.getFilteredCompanies = function() {

        var companies = c.data.companies || [];
        var results = [];

        var searchText = String(c.search || '')
            .toLowerCase()
            .trim();


        for (var i = 0; i < companies.length; i++) {

            var company = companies[i];

            var matchesSearch = true;
            var matchesStatus = true;
            var matchesIndustry = true;


            /*
             * SEARCH
             */

            if (searchText) {

                var searchable =
                    String(company.name || '') + ' ' +
                    String(company.id || '') + ' ' +
                    String(company.industry || '') + ' ' +
                    String(company.recruiter || '') + ' ' +
                    String(company.email || '') + ' ' +
                    String(company.type || '');

                searchable =
                    searchable.toLowerCase();

                matchesSearch =
                    searchable.indexOf(searchText) !== -1;
            }


            /*
             * STATUS
             */

            if (c.statusFilter !== 'all') {

                matchesStatus =
                    String(company.status || '') ===
                    String(c.statusFilter);

            }


            /*
             * INDUSTRY
             */

            if (c.industryFilter !== 'all') {

                matchesIndustry =
                    String(company.industry || '') ===
                    String(c.industryFilter);

            }


            if (
                matchesSearch &&
                matchesStatus &&
                matchesIndustry
            ) {

                results.push(company);

            }

        }

        return results;
    };


    /*
     * =========================================================
     * OPEN COMPANY
     * =========================================================
     */

    c.openCompany = function(company) {

        c.selectedCompany = company;

    };


    /*
     * =========================================================
     * CLOSE COMPANY
     * =========================================================
     */

    c.closeCompany = function() {

        c.selectedCompany = null;

    };


    /*
     * =========================================================
     * ADD COMPANY
     *
     * For now this opens the standard ServiceNow
     * Company Master creation form.
     * =========================================================
     */

    c.openCreate = function() {

        window.location.href =
            '/x_snc_campus360_company_master.do?sys_id=-1';

    };


    /*
     * =========================================================
     * REFRESH
     * =========================================================
     */

    c.refresh = function() {

        c.server.update();

    };

};

sp_widget.css:
/* ==========================================================================
   ULTIMATE FULLSCREEN EDGE-TO-EDGE RESET (HIDES SERVICENOW TOP BANNER & NAVBAR)
   ========================================================================== */

html, body, #sp-page, .sp-page-container, #page_content, .page, main {
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  background-color: #f8fafc !important;
}

/* HIDE SERVICENOW TOP BANNER & NAVBAR FOR ALL TPO PAGE ROOT CONTAINERS */
body #sp-header,
body .sp-header,
body .sp-navbar,
body #sp-nav-bar,
body .sp-nav-bar,
body header#sp-header,
body header.sp-header,
body header.navbar,
body nav.navbar,
body .navbar.sp-navbar,
body .navbar.navbar-default,
body .navbar.navbar-inverse,
#sp-header,
.sp-header,
.sp-navbar,
#responsiveNav,
header#sp-header,
header.sp-header,
header.navbar,
nav.navbar {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  min-height: 0 !important;
  max-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
}

/* ZERO MARGIN & PADDING ON SERVICENOW PAGE CONTAINERS */
.page,
#sp-page,
#sp-main,
.sp-page,
.sp-main,
.page-wrapper,
.main-content,
.container,
.container-fluid,
.row {
