}

/* ==========================================================================
   COMPANIES & INTERVIEWS - FULLSCREEN EDGE-TO-EDGE & PURPLE SIDEBAR FIX
   ========================================================================== */

/* 1. HIDE SERVICENOW TOP BANNER COMPLETELY */
body #sp-header,
body .sp-header,
body .sp-navbar,
body .navbar.sp-navbar,
body #sp-nav-bar,
body .sp-nav-bar,
body header#sp-header,
body header.sp-header,
body .nav.navbar-nav,
#sp-header,
.sp-header,
.sp-navbar,
header#sp-header,
header.sp-header,
.navbar {
  display: none !important;
  height: 0 !important;
  min-height: 0 !important;
  max-height: 0 !important;
  visibility: hidden !important;
