/* =========================================================
   CAMPUS360 TPO FULL SCREEN EDGE-TO-EDGE RESET
   ========================================================= */

body #sp-header,
body .sp-header,
body .sp-navbar,
body .navbar.sp-navbar,
body #sp-nav-bar,
body .sp-nav-bar,
body header#sp-header,
body header.sp-header,
body .nav.navbar-nav {
    display: none !important;
}

html, body {
    width: 100% !important;
    height: 100% !important;
    min-width: 100% !important;
    min-height: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: hidden !important;
    background: #f8fafc !important;
}

body .page,
body #sp-page,
body #sp-main,
body .sp-page,
body .sp-main,
body main,
body .container,
body .container-fluid,
body .row,
body [class*="col-"] {
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    border: none !important;
}

.campus360-company-page {
  padding: 32px;
  max-width: 1400px;
  margin: 0 auto;
  color: #18233f;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}


/* =========================================================
   HEADER
   ========================================================= */

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 24px;
  margin-bottom: 28px;
}

.eyebrow,
.card-eyebrow {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.4px;
  color: #6941d9;
  margin-bottom: 7px;
}

.page-header h1 {
  margin: 0;
  font-size: 32px;
  font-weight: 800;
  color: #111b38;
}

.page-header p {
  margin: 8px 0 0;
  color: #71809c;
  font-size: 14px;
  line-height: 1.6;
}


/* =========================================================
   BUTTONS
   ========================================================= */

.header-actions {
  display: flex;
  gap: 10px;
}

.primary-btn,
.secondary-btn,
.view-btn,
.close-btn {
  cursor: pointer;
}

.primary-btn,
.secondary-btn {
  border-radius: 9px;
  padding: 10px 15px;
  font-size: 13px;
  font-weight: 700;
  border: 1px solid transparent;
}

.primary-btn {
  background: #6941d9;
  color: #fff;
}

.primary-btn:hover {
  background: #5631bd;
}

.secondary-btn {
  background: #fff;
  color: #46536d;
  border-color: #dfe4ee;
}

.secondary-btn:hover {
  background: #f7f8fb;
}


/* =========================================================
   SUMMARY
   ========================================================= */

.summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 22px;
}

.summary-card {
  display: flex;
  align-items: center;
  gap: 14px;
  background: #fff;
  border: 1px solid #e7ebf2;
  border-radius: 14px;
  padding: 19px;
  box-shadow: 0 3px 12px rgba(31, 43, 75, .04);
}

.summary-icon {
  width: 42px;
  height: 42px;
  border-radius: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 700;
}

.summary-card span {
  display: block;
  color: #77839b;
  font-size: 12px;
  margin-bottom: 4px;
}

.summary-card strong {
  font-size: 24px;
  color: #18233f;
}

.summary-card.blue .summary-icon {
  background: #edf4ff;
  color: #3978db;
}

.summary-card.green .summary-icon {
  background: #eaf8f0;
  color: #27945d;
}

.summary-card.gray .summary-icon {
  background: #f0f2f5;
  color: #758198;
}

.summary-card.purple .summary-icon {
  background: #f1edff;
  color: #6941d9;
}


/* =========================================================
   FILTER
   ========================================================= */

.filter-card {
  display: flex;
  gap: 12px;
  align-items: center;
  background: #fff;
  border: 1px solid #e6eaf1;
  border-radius: 14px;
  padding: 14px;
  margin-bottom: 22px;
  box-shadow: 0 3px 12px rgba(31, 43, 75, .04);
}

.search-box {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 1;
  min-width: 280px;
  background: #f7f8fb;
  border: 1px solid #e4e8f0;
  border-radius: 9px;
  padding: 0 12px;
}

.search-icon {
  font-size: 18px;
  color: #8b96aa;
}

.search-box input {
  width: 100%;
  border: 0;
  outline: none;
  background: transparent;
  padding: 11px 0;
  font-size: 13px;
}

.filter-card select {
  min-width: 180px;
  padding: 11px 12px;
  border: 1px solid #dfe4ed;
  border-radius: 9px;
  background: #fff;
  color: #46536d;
  font-size: 13px;
}


/* =========================================================
   COMPANY CARD
   ========================================================= */

.company-card {
  background: #fff;
  border: 1px solid #e6eaf1;
  border-radius: 15px;
  padding: 22px;
  box-shadow: 0 3px 12px rgba(31, 43, 75, .04);
  margin-bottom: 20px;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 15px;
  margin-bottom: 20px;
}

.card-header h2 {
  margin: 0;
  font-size: 19px;
  font-weight: 800;
  color: #17213b;
}

.card-header p {
  margin: 5px 0 0;
  color: #8a95a8;
  font-size: 12px;
}

.record-count {
  background: #f3f5f9;
  color: #68748b;
  border-radius: 8px;
  padding: 7px 10px;
  font-size: 11px;
  font-weight: 700;
}


/* =========================================================
   TABLE
   ========================================================= */

.table-wrapper {
  overflow-x: auto;
}

.company-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 1000px;
}

.company-table th {
  text-align: left;
  padding: 12px 10px;
  background: #f7f8fb;
  color: #758198;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .7px;
  text-transform: uppercase;
}

.company-table td {
  padding: 14px 10px;
  border-bottom: 1px solid #edf0f5;
  color: #46536d;
  font-size: 12px;
}

.company-table tbody tr:hover {
  background: #fafbfe;
}


/* =========================================================
   COMPANY CELL
   ========================================================= */

.company-cell {
  display: flex;
  align-items: center;
  gap: 11px;
}

.company-avatar,
.large-company-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: #f1edff;
  color: #6941d9;
  font-weight: 800;
}

.company-avatar {
  width: 36px;
  height: 36px;
  font-size: 11px;
}

.company-cell strong {
  display: block;
  color: #25304a;
  font-size: 13px;
}

.company-cell span {
  display: block;
  margin-top: 3px;
  color: #9099a9;
  font-size: 10px;
}


/* =========================================================
   RECRUITER
   ========================================================= */

.recruiter-cell strong {
  display: block;
  color: #34405a;
  font-size: 12px;
}

.recruiter-cell span {
  display: block;
  margin-top: 3px;
  color: #8b95a8;
  font-size: 10px;
}


/* =========================================================
   PILLS
   ========================================================= */

.industry-pill,
.type-pill {
  display: inline-block;
  padding: 5px 8px;
  border-radius: 7px;
  background: #f3f5f9;
  color: #59667d;
  font-size: 10px;
  font-weight: 700;
}

.status-pill {
  display: inline-block;
  padding: 5px 9px;
  border-radius: 20px;
  font-size: 10px;
  font-weight: 700;
}

.status-active {
  background: #eaf8f0;
  color: #27945d;
}

.status-inactive {
  background: #f1f3f6;
  color: #7d8798;
}


/* =========================================================
   VIEW BUTTON
   ========================================================= */

.view-btn {
  border: 0;
  background: transparent;
  color: #6941d9;
  font-size: 11px;
  font-weight: 800;
  padding: 5px;
}

.view-btn:hover {
  text-decoration: underline;
}


/* =========================================================
   EMPTY
   ========================================================= */

.empty-state {
  padding: 55px 20px;
  text-align: center;
  color: #8b95a8;
}

.empty-icon {
  font-size: 30px;
  margin-bottom: 10px;
  color: #b1b9c7;
}

.empty-state strong {
  display: block;
  color: #5f6b81;
  font-size: 13px;
}

.empty-state span {
  display: block;
  margin-top: 5px;
  font-size: 11px;
}


/* =========================================================
   DETAIL PANEL
   ========================================================= */

.detail-overlay {
  position: fixed;
  inset: 0;
  background: rgba(16, 25, 48, .35);
  z-index: 1000;
  display: flex;
  justify-content: flex-end;
}

.detail-panel {
  width: 480px;
  max-width: 90vw;
  height: 100%;
  background: #fff;
  padding: 28px;
  overflow-y: auto;
  box-shadow: -8px 0 30px rgba(20, 30, 55, .15);
}

.detail-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 25px;
}

.detail-header h2 {
  margin: 0;
  font-size: 23px;
  color: #18233f;
}

.close-btn {
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 8px;
  background: #f3f5f8;
  color: #59657b;
  font-size: 22px;
}

.detail-company-head {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px;
  background: #f8f9fc;
  border-radius: 12px;
  margin-bottom: 22px;
}

.large-company-avatar {
  width: 52px;
  height: 52px;
  font-size: 15px;
}

.detail-company-head strong {
  display: block;
  font-size: 15px;
}

.detail-company-head span {
  display: block;
  margin-top: 4px;
  color: #8a95a8;
  font-size: 11px;
}

.detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
}

.detail-field {
  padding: 13px;
  background: #f8f9fb;
  border-radius: 9px;
}

.detail-field span {
  display: block;
  color: #8a95a8;
  font-size: 10px;
  margin-bottom: 5px;
}

.detail-field strong {
  display: block;
  color: #39455e;
  font-size: 12px;
  word-break: break-word;
}

.detail-actions {
  margin-top: 25px;
  display: flex;
  justify-content: flex-end;
}


/* =========================================================
   FOOTER
   ========================================================= */

.page-footer {
  display: flex;
  justify-content: space-between;
  color: #8994a8;
  font-size: 11px;
  padding: 5px 2px 20px;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1000px) {

  .summary-grid {
    grid-template-columns: repeat(2, 1fr);
  }

}

@media (max-width: 700px) {

  .campus360-company-page {
    padding: 20px;
  }

  .page-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .filter-card {
    flex-wrap: wrap;
  }

  .search-box {
    flex-basis: 100%;
  }

  .summary-grid {
    grid-template-columns: 1fr;
  }

  .detail-panel {
    width: 100%;
    max-width: 100%;
  }

  .detail-grid {
    grid-template-columns: 1fr;
  }

}
