sp_widget.script:
(function() {
  try { data.chatbotWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5', {}); } catch(e) {}

    /*
     * =========================================================
     * CAMPUS360 TPO COMPANIES
     * Server-side data provider
     * =========================================================
     */

    data.companies = [];

    data.industries = [];

    data.stats = {
        total: 0,
        active: 0,
        inactive: 0,
        industries: 0
    };


    /*
     * =========================================================
     * COMPANY MASTER
     * =========================================================
     */

    var companyGR = new GlideRecord(
        'x_snc_campus360_company_master'
    );

    companyGR.orderBy('company_name');
    companyGR.query();


    var industryMap = {};


    while (companyGR.next()) {

        var companyName =
            companyGR.getValue('company_name') || '';

        var companyId =
            companyGR.getValue('company_id') || '';

        var industry =
            companyGR.getDisplayValue('industry') ||
            companyGR.getValue('industry') ||
            '';

        var recruiterName =
            companyGR.getValue('recruiter_name') || '';

        var recruiterEmail =
            companyGR.getValue('recruiter_email') || '';

        var contactNumber =
            companyGR.getValue('contact_number') || '';

        var companyType =
            companyGR.getDisplayValue('company_type') ||
            companyGR.getValue('company_type') ||
            '';

        var status =
            companyGR.getDisplayValue('status') ||
            companyGR.getValue('status') ||
            '';


        /*
         * =====================================================
         * INITIALS
         * =====================================================
         */

        var initials = '';

        if (companyName) {

            var words =
                companyName.trim().split(/\s+/);

            if (words.length === 1) {

                initials =
                    words[0].substring(0, 2);

            } else {

                initials =
                    words[0].charAt(0) +
                    words[1].charAt(0);

            }

        }

        initials =
            initials.toUpperCase();


        /*
         * =====================================================
         * COMPANY OBJECT
         * =====================================================
         */

        data.companies.push({

            sys_id: companyGR.getUniqueValue(),

            id: companyId,

            name: companyName,

            industry: industry,

            recruiter: recruiterName,

            email: recruiterEmail,

            contact: contactNumber,

            type: companyType,

            status: status,

            initials: initials

        });


        /*
         * =====================================================
         * STATISTICS
         * =====================================================
         */

        data.stats.total++;


        if (status === 'Active') {

            data.stats.active++;

        } else {

            data.stats.inactive++;

        }


        /*
         * =====================================================
         * INDUSTRY
         * =====================================================
         */

        if (industry) {

            industryMap[industry] = true;

        }

    }


    /*
     * =========================================================
     * INDUSTRY LIST
     * =========================================================
     */

    for (var industryName in industryMap) {

        if (
            industryMap.hasOwnProperty(industryName)
        ) {

            data.industries.push(
                industryName
            );

        }

    }


    data.industries.sort();

    data.stats.industries =
        data.industries.length;


})();

